contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single test function: send an arbitrary amount 'amt' from this contract to c.Deposit()
    // rule: for amt < MinDeposit, balances[this] must remain 0 (P enforces this by ignoring too-small deposits;
    // the mutant inverts the condition and would instead accept small deposits causing balances[this] > 0)
    function run(uint256 amt) public {
        // ensure this contract has enough balance to send
        require(address(this).balance >= amt);

        // call Deposit on C, sending amt wei
        c.Deposit{value: amt}();

        // observe balance for this contract in C
        uint stored = c.balances(address(this));
        uint min = c.MinDeposit();

        // assertion: if we sent less than MinDeposit then stored balance must be zero
        assert(!(amt < min) || (stored == 0));
    }

    // allow funding this contract for the test
    receive() external payable {}
    fallback() external payable {}
}

