contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // single test entrypoint
    // params: depositor address (as payable via this contract), deposit amount
    // We require this contract has enough ETH to forward amount.
    function run(address payable who, uint amount) public {
        // preconditions: amount qualifies as a deposit
        require(amount >= c.MinDeposit());
        require(amount > 0);
        // ensure this test contract holds the funds to forward
        require(address(this).balance >= amount);

        // record pre-state: balances and contract c's balance
        uint before_bal = c.balances(who);
        uint before_c_balance = address(c).balance;

        // perform Deposit call on behalf of `who` by using low-level call with value
        // we must invoke c.Deposit() with msg.sender == who. To do that we expect
        // that the test harness will call this function with `who == address(this)`
        // when appropriate. But to remain general, we perform the deposit from this contract
        // and then assert the effect relative to the depositor 'who'.
        // Call Deposit sending the amount from this contract
        c.Deposit{value: amount}();

        // observe post-state
        uint after_bal = c.balances(who);
        uint after_c_balance = address(c).balance;

        // The general rule: if Deposit accepted the funds, then the recorded balance
        // for the depositor increased by amount and the contract balance increased by amount.
        // We express it as: after_bal == before_bal + amount && after_c_balance == before_c_balance + amount
        // This holds for original P but is violated by M which prevents deposits (require(msg.value==0)).
        assert(after_bal == before_bal + amount && after_c_balance == before_c_balance + amount);
    }

    // allow this test contract to receive ETH so it can forward deposits
    receive() external payable {}
}

