pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this)); }

    // Fuzzed params: depositor and attacker amounts
    // We fuzz two amounts and two actors to allow the fuzzer to find sequences that exhibit the mutant's incorrect overwrite
    function testFuzz_property(address depositor, address other, uint256 depAmt, uint256 cashOutAmt) public {
        // Keep addresses non-zero and distinct
        vm.assume(depositor != address(0));
        vm.assume(other != address(0));
        vm.assume(depositor != other);

        // Bound amounts to reasonable ether ranges and ensure min deposit >= 1 wei in reference (1 ether in contract)
        // but we do not restrict too tightly so fuzzer can find interesting values; use 0..5 ether
        uint256 dAmt = bound(depAmt, 0.001 ether, 5 ether);
        uint256 cAmt = bound(cashOutAmt, 0, 5 ether);

        // Fund depositor and other so they can send
        vm.deal(depositor, dAmt + 1 ether);
        vm.deal(other, 1 ether);

        // depositor makes a Deposit (may be ignored by contract if below MinDeposit)
        vm.prank(depositor);
        (bool depOk,) = address(c).call{value: dAmt}(abi.encodeWithSignature("Deposit()"));
        // record stored balance for depositor after deposit
        uint256 bal_after_deposit = c.balances(depositor);

        // Now let depositor attempt a CashOut of cAmt (may revert if > balance)
        bool ok;
        vm.prank(depositor);
        try c.CashOut(cAmt) { ok = true; } catch { ok = false; }

        // After CashOut attempt, read balances for depositor and other
        uint256 bal_after = c.balances(depositor);
        uint256 other_bal_after = c.balances(other);

        // GENERAL ASSERTION (single assertTrue): For the correct contract, deposits only increase an address's stored balance by the deposited amount (they are additive), so after CashOut the depositor's stored balance cannot be larger than the prior balance plus any future deposit of another actor; more simply, the reference preserves that the depositor's balance after CashOut is never less than zero and never decreases below what arithmetic would expect when cashout succeeded.
        // We assert a universal property the reference always satisfies: balances are consistent with non-negative accounting for the depositor — i.e., bal_after == bal_after_deposit - (ok ? (cAmt <= bal_after_deposit ? cAmt : 0) : 0)
        // Rewriting to a safe check: if the CashOut reported success (ok) then bal_after + cAmt == bal_after_deposit (when cAmt<=bal_after_deposit), else bal_after == bal_after_deposit.

        bool prop;
        if (ok) {
            if (cAmt <= bal_after_deposit) {
                prop = (bal_after + cAmt == bal_after_deposit);
            } else {
                // In reference, CashOut should have reverted if trying to withdraw more than balance, so ok shouldn't be true when cAmt > bal_after_deposit
                prop = false;
            }
        } else {
            // If CashOut failed, balance must be unchanged
            prop = (bal_after == bal_after_deposit);
        }

        // Single assertion reading c's public getters that the correct contract will always make true;
        // The mutant that overwrites balances on Deposit can break this accounting relationship for some fuzzed inputs
        assertTrue(prop);
    }
}

