        d1 = bound(d1, 1 ether, 100 ether);
        d2 = bound(d2, 1 ether, 100 ether);
        // withdrawal amount bounded to [0, 200 ether]
        w = bound(w, 0, 200 ether);

        // 1) depositor D makes an initial deposit d1
        vm.deal(D, d1);
        vm.prank(D);
        c.Deposit{value: d1}();

        // record D's balance after first deposit
        uint256 before = c.balances(D);

        // 2) attacker A receives some funds and attempts to withdraw up to w after ensuring it has a deposit
        // Ensure A has some deposit so CashOut can be exercised (may or may not succeed depending on amounts)
        uint256 fundA = d2 + w;
        vm.deal(A, fundA);
        vm.prank(A);
        c.Deposit{value: d2}();

