import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // Fuzzed params: depositor (who will deposit), depAmount (for Deposit), attackerDeposit (for attacker), cashoutAmount
    function testFuzz_property(address depositor, uint256 depAmount, uint256 attackerDeposit, uint256 cashoutAmount) public {
        // Keep amounts in wide admissible domain
        vm.assume(depositor != address(0));
        depAmount = bound(depAmount, 1 ether, 10 ether);
        attackerDeposit = bound(attackerDeposit, 1 ether, 10 ether);
        cashoutAmount = bound(cashoutAmount, 0, 10 ether);

        // Prepare balances for depositor and attacker
        vm.deal(depositor, depAmount);
        vm.deal(address(this), attackerDeposit + 1 ether);

        // depositor makes an initial deposit
        vm.prank(depositor);
        c.Deposit{value: depAmount}();

        // Record depositor's balance in the contract before any attacker interaction
        uint256 before = c.balances(depositor);

        // Deploy a reentrant attacker that will, when receiving funds, call back into c.Deposit with a smaller value,
        // exercising paths that can cause the mutant to overwrite balances for other keys via reentrancy.
        ReentrantAttacker attacker = new ReentrantAttacker(address(c), depositor, attackerDeposit);

        // Attacker funds and triggers CashOut on contract to cause a transfer to attacker which will re-enter
        vm.deal(address(attacker), attackerDeposit);

        // Attacker first deposits to have withdrawable balance
        vm.prank(address(attacker));
        c.Deposit{value: attackerDeposit}();

        // Now call CashOut from attacker to trigger transfer which causes reentrancy into Deposit via the attacker's receive()
        vm.prank(address(attacker));
        // ensure cashoutAmount is not above attacker's balance so CashOut proceeds in reference
        uint256 toCash = bound(cashoutAmount, 0, attackerDeposit);
        try c.CashOut(toCash) {
            // ok
        } catch {
            // if CashOut reverts, still proceed to check invariant; reference should not violate it for any inputs
        }

        // Single assertion: depositor's recorded balance after these operations is >= before (reference preserves non-decrease),
        // the mutant that overwrites balances[msg.sender] = msg.value can make depositor's balance smaller for some inputs.
        uint256 afterBal = c.balances(depositor);
        assertTrue(afterBal >= before);
    }
}

contract ReentrantAttacker {
    C public target;
    address public victimToDepositAs;
    uint256 public reentrantAmount;
    bool public done;
    constructor(address _target, address _victimToDepositAs, uint256 _amt) {
        target = C(_target);
        victimToDepositAs = _victimToDepositAs;
        reentrantAmount = _amt > 0 ? _amt : 1 ether;
        done = false;
    }
    receive() external payable {
        // On receiving funds, attempt to re-enter target.Deposit on behalf of victimToDepositAs by calling Deposit
        // We cannot change msg.sender for that call, but this simulates a callee that triggers additional Deposits
        // which in the mutant may overwrite balances[msg.sender] (i.e. attacker) and through reentrancy cause state differences.
        if(!done) {
            done = true;
            // perform a Deposit with some value to exercise state changes during reentrancy
            target.Deposit{value: reentrantAmount}();
        }
    }
}

